for c in peer.get('macro_material_challenge_families',[]): items.append({'id':c['family_id'],'family':c['family_id'],'ids':c['decision_ids'],'passage':c['envelope'],'claim':c['material_challenge'],'alts':c['exact_alternatives']})
g=peer['global_textual_translation_addressee_quotation_hot_zone_challenge'];items.append({'id':g['challenge_id'],'family':'global textual translation quotation speaker and chronology hot zones','ids':[f'M7_sol-Eph-{i:03d}' for i in range(1,17)],'passage':'; '.join(g['spans']),'claim':'All witness, reading, translation, punctuation, addressee, quotation-source, quotation-extent, and quotation-speaker questions remain unresolved evidence; the frozen route selects none.','alts':['retain every frozen seam with all hot-zone flags deferred','retain each corresponding larger macro parent with all hot-zone flags deferred']})
